from pathlib import Path

path = Path("index.html")
text = path.read_text(encoding="utf-8")
old = 'function questionComplete(q){return isSubmitted(q)}'
new = "function questionComplete(q){if(!isSubmitted(q))return false;if(q.type==='mcq')return String(getChoice(q))===String(q.correct);return true}"
if old not in text:
    raise SystemExit("questionComplete da versão 18 não encontrado")
text = text.replace(old,new,1)
anchor = '.topicDone{margin-top:16px;background:linear-gradient(135deg,#173026 0%,#1b3d30 100%);'
css_insert = "/* Estados visuais da questão após responder */\n.question{transition:background .25s ease,opacity .25s ease,filter .25s ease,border-color .25s ease}\n.question.stateCorrect{background:linear-gradient(180deg,rgba(238,249,242,.76) 0%,rgba(248,252,249,.82) 100%)}\n.question.stateCorrect>.reviewCard,.question.stateCorrect>.qTitle,.question.stateCorrect>.mcqLayout,.question.stateCorrect>.options,.question.stateCorrect>.board,.question.stateCorrect>.actions{opacity:.52;filter:saturate(.72)}\n.question.stateWrong{background:linear-gradient(180deg,#f1f3f2 0%,#f7f8f8 100%)}\n.question.stateWrong>.reviewCard,.question.stateWrong>.qTitle,.question.stateWrong>.mcqLayout,.question.stateWrong>.options,.question.stateWrong>.board{opacity:.48;filter:grayscale(.72)}\n.question.stateWrong .actions .btn:not(.retryActive){opacity:.42}\n.question .statusSeal{display:none;margin-top:12px;padding:8px 11px;border-radius:999px;width:max-content;max-width:100%;font-size:12px;font-weight:900}\n.question.stateCorrect .statusSeal{display:inline-flex;background:#e3f5e9;color:#17683a;border:1px solid #bfe3cb}\n.question.stateWrong .statusSeal{display:inline-flex;background:#e5e7e6;color:#525c56;border:1px solid #d1d5d3}\n.explainGate.consumed{display:flex!important;opacity:.46;filter:grayscale(.65);pointer-events:none}\n.explainGate.consumed .btn{display:none}\n.explainer.consumed{display:block;opacity:.82;filter:saturate(.8)}\n.explainer.consumed::after{content:'✓ Explicação lida';display:block;margin:0 16px 16px;padding:9px 11px;border-radius:12px;background:#eef1f0;border:1px solid #d9dfdc;color:#59655f;font-size:12px;font-weight:900;text-align:center}\n.btn.retryActive{background:linear-gradient(135deg,#34423a 0%,#202b25 100%);border-color:#34423a;color:#fff;box-shadow:0 9px 18px rgba(31,41,36,.18)}\n@media (prefers-reduced-motion:reduce){.question{transition:none}}\n"
if anchor not in text:
    raise SystemExit("âncora CSS da versão 18 não encontrada")
text = text.replace(anchor, css_insert + anchor, 1)
start = text.find("function buildQuestion(q,num){")
end = text.find("\nfunction setCanvasLocked(board,locked){", start)
if start < 0 or end < 0:
    raise SystemExit("buildQuestion da versão 18 não encontrado")
new_func = 'function buildQuestion(q,num){\n  const card=document.createElement(\'article\');card.className=\'question\';\n  const review=document.createElement(\'div\');\n  const reviewTheme=getReviewTheme();\n  review.className=`reviewCard ${reviewTheme.className}`;\n  review.innerHTML=buildPreQuestionReview(q);\n  card.appendChild(review);\n  const head=document.createElement(\'div\');head.className=\'qTitle\';head.innerHTML=`<div class="badge">${num}</div><div><div class="qMeta">${q.type===\'mcq\'?\'Múltipla escolha\':\'Resposta à mão\'}</div><strong>${q.text}</strong></div>`;card.appendChild(head);\n  const statusSeal=document.createElement(\'div\');statusSeal.className=\'statusSeal\';card.appendChild(statusSeal);\n  const actions=document.createElement(\'div\');actions.className=\'actions\';\n  const submit=document.createElement(\'button\');submit.type=\'button\';submit.className=\'btn primary\';submit.textContent=isSubmitted(q)?\'Resposta enviada\':\'Enviar resposta\';\n  const redo=document.createElement(\'button\');redo.type=\'button\';redo.className=\'btn secondary\';redo.textContent=\'Responder novamente\';redo.style.display=\'none\';\n  const feedback=document.createElement(\'span\');feedback.className=\'feedback\';\n  const gate=document.createElement(\'div\');gate.className=\'explainGate\';\n  const explainButton=document.createElement(\'button\');explainButton.type=\'button\';explainButton.className=\'btn primary\';explainButton.textContent=\'Abrir explicação\';\n  gate.innerHTML=`<div class="explainGateText"><div class="explainGateIcon">💡</div><div><strong>Explicar esta questão</strong><span>Agora que a resposta foi enviada, veja a explicação de forma visual.</span></div></div>`;gate.appendChild(explainButton);\n  const gateIcon=gate.querySelector(\'.explainGateIcon\');\n  const gateTitle=gate.querySelector(\'strong\');\n  const gateDesc=gate.querySelector(\'span\');\n  const explainer=document.createElement(\'div\');explainer.className=\'explainer\';\n  let currentHasAnswer=false;\n\n  const isWrong=()=>q.type===\'mcq\'&&isSubmitted(q)&&String(getChoice(q))!==String(q.correct);\n  const isCorrect=()=>q.type!==\'mcq\'?isSubmitted(q):(isSubmitted(q)&&String(getChoice(q))===String(q.correct));\n  const wasExplained=()=>localStorage.getItem(key(q.id,\'explained\'))===\'1\';\n\n  function renderExplainer(){\n    let status=\'\';\n    if(q.type===\'mcq\'){\n      const choice=getChoice(q);const ok=String(choice)===String(q.correct);\n      status=`<div class="${ok?\'resultGood\':\'resultTry\'}">${ok?\'✅ Você acertou!\':\'❌ Você errou. Vamos entender o que aconteceu.\'}</div>`;\n    }else{\n      status=\'<div class="resultGood">✍️ Compare o que você escreveu com a ideia principal.</div>\';\n    }\n    const everyday=q.everyday||DAILY_EXAMPLES[q.id];\n    const rememberHtml=everyday?`<div class="everyday"><div class="everydayTitle">🧠 Guarde esta ideia</div><div class="remember">${everyday.remember}</div></div>`:\'\';\n    explainer.innerHTML=`<div class="explainTop"><h5>Vamos entender juntos</h5><p>${status}<br>${q.explanation}</p></div><div class="visual">${q.visual}</div>${rememberHtml}<div class="expected">${q.expected}</div>`;\n  }\n  renderExplainer();\n\n  function applyCardState(){\n    const submitted=isSubmitted(q),wrong=isWrong(),correct=isCorrect(),explained=wasExplained();\n    card.classList.toggle(\'stateCorrect\',submitted&&correct);\n    card.classList.toggle(\'stateWrong\',submitted&&wrong);\n    card.classList.toggle(\'explanationRead\',submitted&&explained);\n    if(submitted&&correct){statusSeal.textContent=\'✓ Questão concluída\';}\n    else if(submitted&&wrong&&!explained){statusSeal.textContent=\'Resposta incorreta. Leia a explicação para tentar outra vez.\';}\n    else if(submitted&&wrong&&explained){statusSeal.textContent=\'Explicação lida. Agora tente novamente.\';}\n    else statusSeal.textContent=\'\';\n  }\n\n  function updateState(){\n    const submitted=isSubmitted(q),wrong=isWrong(),correct=isCorrect(),explained=wasExplained();\n    if(q.type===\'mcq\') currentHasAnswer=getChoice(q)!==null;\n    else currentHasAnswer=!!getCanvas(q);\n    submit.disabled=!currentHasAnswer||submitted;\n    submit.textContent=submitted?\'Resposta enviada\':\'Enviar resposta\';\n    redo.classList.toggle(\'retryActive\',submitted&&wrong&&explained);\n    redo.style.display=submitted&&wrong&&explained?\'inline-flex\':\'none\';\n    gate.classList.remove(\'success\',\'error\',\'consumed\');\n    feedback.className=\'feedback\';\n    applyCardState();\n\n    if(submitted){\n      gate.classList.toggle(\'show\',!explained);\n      if(explained){\n        gate.classList.add(\'consumed\');\n        explainButton.disabled=true;\n      }else explainButton.disabled=false;\n      if(q.type===\'mcq\'){\n        if(correct){\n          gate.classList.add(\'success\');\n          gateIcon.textContent=\'✅\';\n          gateTitle.textContent=\'Resposta correta\';\n          gateDesc.textContent=\'Questão concluída. Se quiser, abra a explicação uma vez.\';\n          feedback.textContent=\'Muito bem! Esta questão foi concluída.\';\n          feedback.classList.add(\'success\');\n        }else{\n          gate.classList.add(\'error\');\n          gateIcon.textContent=\'❌\';\n          gateTitle.textContent=explained?\'Explicação já lida\':\'Você errou\';\n          gateDesc.textContent=explained?\'Agora use Responder novamente para fazer outra tentativa.\':\'Leia a explicação antes de responder novamente.\';\n          feedback.textContent=explained?\'Agora você pode responder novamente.\':\'Primeiro leia a explicação desta questão.\';\n          feedback.classList.add(\'error\');\n        }\n      }else{\n        gate.classList.add(\'success\');\n        gateIcon.textContent=\'💡\';\n        gateTitle.textContent=explained?\'Explicação já lida\':\'Explicar esta questão\';\n        gateDesc.textContent=explained?\'Esta explicação já foi consultada.\':\'Sua resposta foi registrada. Você pode abrir a explicação uma vez.\';\n        feedback.textContent=\'Resposta registrada.\';\n      }\n    }else{\n      gate.classList.remove(\'show\',\'consumed\');\n      explainButton.disabled=false;\n      explainer.classList.remove(\'show\',\'consumed\');\n      gateIcon.textContent=\'💡\';\n      gateTitle.textContent=\'Explicar esta questão\';\n      gateDesc.textContent=\'A explicação será liberada depois que a resposta for enviada.\';\n      feedback.textContent=currentHasAnswer?\'Quando terminar, envie a resposta.\':\'Responda primeiro.\';\n    }\n  }\n\n  function afterExplanationOpened(){\n    localStorage.setItem(key(q.id,\'explained\'),\'1\');\n    gate.classList.remove(\'show\');\n    gate.classList.add(\'consumed\');\n    explainButton.disabled=true;\n    explainer.classList.add(\'show\',\'consumed\');\n    updateState();\n    explainer.classList.add(\'show\',\'consumed\');\n    explainer.scrollIntoView({behavior:\'smooth\',block:\'nearest\'});\n  }\n\n  if(q.type===\'mcq\'){\n    const options=document.createElement(\'div\');options.className=\'options\';\n    const saved=getChoice(q);const submitted=isSubmitted(q);\n    q.options.forEach((opt,idx)=>{\n      const label=document.createElement(\'label\');label.className=\'option\'+(submitted?\' locked\':\'\');\n      const input=document.createElement(\'input\');input.type=\'radio\';input.name=q.id;input.value=idx;input.checked=saved===String(idx);input.disabled=submitted;\n      const span=document.createElement(\'span\');span.textContent=opt;label.appendChild(input);label.appendChild(span);\n      input.addEventListener(\'change\',()=>{localStorage.setItem(key(q.id,\'choice\'),String(idx));explainer.classList.remove(\'show\',\'consumed\');updateState()});\n      options.appendChild(label);\n    });\n    const useScratch=shouldShowScratchpad(q);\n    if(useScratch){\n      const mcqLayout=document.createElement(\'div\');mcqLayout.className=\'mcqLayout\';\n      mcqLayout.appendChild(options);\n      mcqLayout.appendChild(createScratchBoard(q));\n      card.appendChild(mcqLayout);\n    }else{\n      card.appendChild(options);\n    }\n\n    function lockOptions(showResult=false){\n      const choice=getChoice(q);options.querySelectorAll(\'.option\').forEach((label,idx)=>{const input=label.querySelector(\'input\');input.disabled=isSubmitted(q);label.classList.toggle(\'locked\',isSubmitted(q));label.classList.remove(\'correct\',\'wrong\');if(showResult&&isSubmitted(q)){if(idx===q.correct)label.classList.add(\'correct\');if(String(idx)===String(choice)&&idx!==q.correct)label.classList.add(\'wrong\')}})\n    }\n\n    submit.addEventListener(\'click\',()=>{\n      if(!currentHasAnswer)return;\n      localStorage.setItem(key(q.id,\'submitted\'),\'1\');localStorage.removeItem(key(q.id,\'explained\'));\n      explainer.classList.remove(\'show\',\'consumed\');lockOptions(false);updateState();updateProgress();\n      if(isCorrect())toast(\'Muito bem! Questão concluída.\');\n      else toast(\'Resposta incorreta. Leia a explicação antes de tentar novamente.\');\n    });\n    redo.addEventListener(\'click\',()=>{\n      if(!isWrong()||!wasExplained())return;\n      localStorage.removeItem(key(q.id,\'submitted\'));localStorage.removeItem(key(q.id,\'explained\'));localStorage.removeItem(key(q.id,\'choice\'));\n      options.querySelectorAll(\'input\').forEach(input=>{input.checked=false});\n      explainer.classList.remove(\'show\',\'consumed\');gate.classList.remove(\'show\',\'consumed\');lockOptions(false);updateState();updateProgress();\n      card.scrollIntoView({behavior:\'smooth\',block:\'center\'});\n    });\n    explainButton.addEventListener(\'click\',()=>{if(!isSubmitted(q)||wasExplained())return;renderExplainer();lockOptions(true);afterExplanationOpened()});\n    if(isSubmitted(q)&&wasExplained()){\n      gate.classList.add(\'consumed\');\n      explainer.classList.remove(\'show\');\n    }\n    updateState();\n  } else {\n    const board=document.createElement(\'div\');board.className=\'board\';\n    board.innerHTML=`<div class="toolbar"><button class="tool pen active" type="button">Caneta</button><button class="tool eraser" type="button">Borracha</button><button class="tool undo" type="button">Desfazer</button><button class="tool danger clear" type="button">Limpar</button><span class="sep"></span><span class="sizeLabel">Espessura</span><input class="sizeRange" type="range" min="1" max="12" value="4"><span class="sizeValue">4 px</span></div><div class="canvasWrap"><canvas class="answerCanvas"></canvas></div><div class="penHint">Use a caneta do tablet ou o dedo. Nesta pergunta não há teclado.</div>`;\n    card.appendChild(board);\n    setupCanvas(board,q,()=>{currentHasAnswer=!!getCanvas(q);updateState()},()=>isSubmitted(q));\n\n    submit.addEventListener(\'click\',()=>{if(!currentHasAnswer)return;localStorage.setItem(key(q.id,\'submitted\'),\'1\');localStorage.removeItem(key(q.id,\'explained\'));board.classList.add(\'submittedBoard\');explainer.classList.remove(\'show\',\'consumed\');setCanvasLocked(board,true);updateState();updateProgress();toast(\'Resposta registrada. Questão concluída.\')});\n    explainButton.addEventListener(\'click\',()=>{if(!isSubmitted(q)||wasExplained())return;renderExplainer();afterExplanationOpened()});\n    if(isSubmitted(q)){board.classList.add(\'submittedBoard\');setTimeout(()=>setCanvasLocked(board,true),0)}\n    if(isSubmitted(q)&&wasExplained())gate.classList.add(\'consumed\');\n    updateState();\n  }\n\n  actions.appendChild(submit);actions.appendChild(redo);actions.appendChild(feedback);card.appendChild(actions);card.appendChild(gate);card.appendChild(explainer);\n  return card;\n}\n'
text = text[:start] + new_func + text[end:]
path.write_text(text,encoding="utf-8")
print(f"versão 19 aplicada: {len(text.encode('utf-8'))} bytes")
